changes.after:
var noteCard=function(point,label,slot){
  var note=typeof point.observation.note==='string'?point.observation.note:'',hasNote=!!note.trim(),heading=uid+'-note-'+slot;
  return h('section',{className:'circuit-comparison-note-card','aria-labelledby':heading},
    h('h5',{id:heading},label+' · '+number(point)),
    h('p',{className:hasNote?'circuit-comparison-note-text':'circuit-comparison-note-empty',dir:'auto'},hasNote?note:t('stem.circuit.comparison_note_empty','No note yet. Describe what you noticed about this reading.')),
    typeof props.reviewNote==='function'&&h('button',{type:'button',className:'circuit-comparison-note-edit','aria-controls':props.noteIdPrefix+point.index,onClick:function(){props.reviewNote(point.index);}},t(hasNote?'stem.circuit.comparison_note_edit':'stem.circuit.comparison_note_add',hasNote?'Edit observation {number} note':'Add observation {number} note').replace('{number}',String(point.index+1))));
};
var signed=function(value,format){return value==null?t('stem.circuit.saved_undetermined','Undetermined'):(value>0?'+':'')+format(value);};

.circuit-active-root .circuit-comparison-notes{min-width:0;margin:18px 0 0;border:1px solid #63858e;border-radius:10px;background:#102b35;color:#dceee8}
.circuit-active-root .circuit-comparison-notes>summary{box-sizing:border-box;min-height:44px;padding:10px 12px;font-size:14px;font-weight:650;line-height:1.7;white-space:normal;overflow-wrap:anywhere;cursor:pointer}
.circuit-active-root .circuit-comparison-notes-help{margin:3px 12px 14px;font-size:14px;line-height:1.75;color:#c4d9df;overflow-wrap:anywhere}
.circuit-active-root .circuit-comparison-notes-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px;padding:0 12px 12px;min-width:0}
.circuit-active-root .circuit-comparison-note-card{display:flex;flex-direction:column;min-width:0;padding:14px;border:1px solid #63858e;border-radius:9px;background:#0d2732}
.circuit-active-root .circuit-comparison-note-card h5{margin:0;font-size:14px;line-height:1.7;color:#e2f3ec;overflow-wrap:anywhere}
.circuit-active-root .circuit-comparison-note-text,.circuit-active-root .circuit-comparison-note-empty{flex:1;margin:12px 0 16px;font-size:14px;line-height:1.75;white-space:pre-wrap;overflow-wrap:anywhere;color:#dceee8}
.circuit-active-root .circuit-comparison-note-empty{color:#b8cbd1}
.circuit-active-root .circuit-comparison-note-edit,.circuit-active-root .circuit-note-comparison-return{box-sizing:border-box;min-height:44px;min-width:0;max-width:100%;padding:10px 12px;border:1px solid #9bccbb;border-radius:9px;background:#254c42;color:#e5f5ed;font-size:14px;font-weight:650;line-height:1.6;white-space:normal;overflow-wrap:anywhere;cursor:pointer}
.circuit-active-root .circuit-note-comparison-return{margin:8px 0 12px}
.circuit-active-root .circuit-comparison-note-edit:hover,.circuit-active-root .circuit-note-comparison-return:hover{background:#315d4f;border-color:#c1e6d5}
.circuit-active-root .circuit-comparison-note-edit:focus-visible,.circuit-active-root .circuit-note-comparison-return:focus-visible,.circuit-active-root .circuit-comparison-notes>summary:focus-visible{outline:3px solid #f2d296;outline-offset:3px}
@media(max-width:640px){.circuit-active-root .circuit-comparison-notes-grid{grid-template-columns:minmax(0,1fr)}.circuit-active-root .circuit-note-comparison-return{width:100%}}
@media(forced-colors:active){.circuit-active-root .circuit-comparison-notes,.circuit-active-root .circuit-comparison-note-card{border-color:CanvasText;background:Canvas;color:CanvasText}.circuit-active-root .circuit-comparison-notes-help,.circuit-active-root .circuit-comparison-note-card h5,.circuit-active-root .circuit-comparison-note-text,.circuit-active-root .circuit-comparison-note-empty{color:CanvasText}.circuit-active-root .circuit-comparison-note-edit,.circuit-active-root .circuit-note-comparison-return{border-color:ButtonText;background:ButtonFace;color:ButtonText}.circuit-active-root .circuit-comparison-note-edit:focus-visible,.circuit-active-root .circuit-note-comparison-return:focus-visible,.circuit-active-root .circuit-comparison-notes>summary:focus-visible{outline-color:Highlight}}
.circuit-active-root .circuit-comparison-writing{min-width:0;margin:20px 0 0;padding:17px 0 0;border-top:1px solid #63888e;color:#dceee8}
